/* * To change this template, choose Tools | Templates * and open the template in the editor. */package net.sf.jiga.xtended.ui;import java.awt.Component;import java.awt.event.ActionEvent;import java.awt.event.ActionListener;import java.util.ArrayList;import javax.swing.JComboBox;/** * A navigator is an extended panel that can handle switching among a list of * indexed panel names, backed by an InstructionsPane. A combo box is generated * and added aside the common prev.<->next. buttons. * * @author www.b23prodtm.info */public class Navigator extends StatusPane {        private JComboBox list;        /**         * @param ownPane provide panel and layout of those panels         */        public Navigator(final InstructionsPane ownPane) {                this(ownPane, new String[ownPane.getSteps()]);                setListPanesEnabled(false);        }        /**         * @param ownPane provide panel and layout of those panels         * @param indexedPanelNames corresponding indexed names of the panels         * indexes         */        public Navigator(final InstructionsPane ownPane, String[] indexedPanelNames) {                super(ownPane, null, null);                list = new JComboBox(indexedPanelNames);                assert indexedPanelNames.length == ownPane.getSteps() : "incorrect array size " + indexedPanelNames.length + " for panel names " + ownPane.getSteps();                add(list);                list.addActionListener(new ActionListener() {                        public void actionPerformed(ActionEvent e) {                                updating = true;                                ownPane.currentStep = list.getSelectedIndex();                                ownPane.updateState();                                ownPane.validate();                                ownPane.repaint();                                updating = false;                        }                });                if (indexedPanelNames[ownPane.getCurrentStep()] != null) {                        list.setSelectedIndex(ownPane.getCurrentStep());                }        }        boolean updating = false;        /**         * enabled by default for the         * {@link #Navigator(net.sf.jiga.xtended.ui.InstructionsPane, java.lang.String[]) constructor with panelnames}         */        public final void setListPanesEnabled(boolean enable) {                if (!enable) {                        remove(list);                } else if (!isListPanesEnabled()) {                        add(list);                }        }        public boolean isListPanesEnabled() {                for (Component c : getComponents()) {                        if (c.equals(list)) {                                return true;                        }                }                return false;        }        /**         * this method can be called from the UI/code to make the panel switch         * as often as needed.         */        @Override        public void stepChanged() {                super.stepChanged();                if (updating) {                        return;                }                if (isListPanesEnabled()) {                        list.setSelectedIndex(ownPane.currentStep);                }        }}